<script setup lang="ts">
import {computed,onBeforeUnmount,ref} from 'vue';
import AppDialog from './AppDialog.vue';
type Publication={id:number;base:string;versao:string;hash_pdf:string;criada_em:string;ciencia_confirmada:boolean};
const props=defineProps<{request:<T>(path:string,method?:string,body?:unknown)=>Promise<T>;download:(path:string)=>Promise<{blob:Blob;type:string}>}>();
const emit=defineEmits<{success:[message:string]}>();
const items=ref<Publication[]>([]),query=ref(''),loading=ref(false),busy=ref(false),error=ref(''),formError=ref(''),confirming=ref<Publication|null>(null),confirmed=ref(false),preview=ref<{item:Publication;url:string}|null>(null);let alive=true,generation=0;
const filtered=computed(()=>items.value.filter(item=>item.base.toLowerCase().includes(query.value.trim().toLowerCase())));
async function load(){const current=++generation;loading.value=true;error.value='';try{const rows=await props.request<Publication[]>('/api/portal/documentos');if(alive&&current===generation)items.value=rows;}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{if(alive&&current===generation)loading.value=false;}}
function closePreview(){if(preview.value)URL.revokeObjectURL(preview.value.url);preview.value=null;}
async function file(item:Publication,download:boolean){if(busy.value)return;busy.value=true;error.value='';const current=generation;try{const result=await props.download(`/api/portal/documentos/${item.id}${download?'?download=1':''}`);if(!alive||current!==generation)return;const url=URL.createObjectURL(result.blob);if(download){const link=document.createElement('a');link.href=url;link.download=item.base.replace(/[^a-z0-9_-]/gi,'_')+'.pdf';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else{closePreview();preview.value={item,url};}}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{busy.value=false;}}
function confirm(item:Publication){confirming.value=item;confirmed.value=false;formError.value='';}
async function acknowledge(){if(!confirming.value||!confirmed.value||busy.value)return;const target=confirming.value,current=generation;busy.value=true;formError.value='';try{await props.request(`/api/portal/documentos/${target.id}/ciencia`,'POST',{confirmo:true});if(!alive||current!==generation)return;confirming.value=null;emit('success','Ciência registrada.');await load();}catch(cause){if(alive&&current===generation)formError.value=(cause as Error).message;}finally{busy.value=false;}}
void load();onBeforeUnmount(()=>{alive=false;generation++;closePreview();});
</script>
<template><section><header class="document-panel-heading"><div><h2>Documentos publicados para esta empresa</h2><p>Consulte as versões disponibilizadas pelo escritório e registre sua ciência.</p></div><button class="secondary" :disabled="busy||loading" @click="load">Atualizar lista</button></header><div class="document-summary"><article><small>Publicações disponíveis</small><strong>{{ items.length }}</strong></article><article><small>Aguardando sua ciência</small><strong>{{ items.filter(item=>!item.ciencia_confirmada).length }}</strong></article></div><div class="registry-controls"><label>Buscar documento publicado<input v-model="query" type="search" placeholder="Número do registro"></label></div><p v-if="loading" role="status">Carregando publicações…</p><p v-if="error" role="alert">{{ error }}</p><div v-if="!loading&&!error" class="registry-scroll"><table><caption>Publicações da empresa</caption><thead><tr><th>Documento</th><th>Publicado em</th><th>Ciência</th><th>Ações</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td><strong>{{ item.base }}</strong><details><summary>Identificação da versão</summary><p class="publication-version">{{ item.versao }}</p><p class="publication-version">SHA-256: {{ item.hash_pdf }}</p></details></td><td>{{ new Date(item.criada_em).toLocaleString('pt-BR') }}</td><td>{{ item.ciencia_confirmada?'Registrada':'Pendente' }}</td><td class="contact-row-actions"><button class="secondary" :disabled="busy" @click="file(item,false)">Abrir documento</button><button class="secondary" :disabled="busy" @click="file(item,true)">Baixar PDF</button><button class="secondary" :disabled="busy||item.ciencia_confirmada" @click="confirm(item)">{{ item.ciencia_confirmada?'Ciência registrada':'Confirmar ciência' }}</button></td></tr><tr v-if="!filtered.length"><td colspan="4">{{ items.length?'Nenhum resultado para esta busca.':'Ainda não há documentos publicados para esta empresa.' }}</td></tr></tbody></table></div></section><AppDialog v-if="preview" title="Documento publicado" @close="closePreview"><h3>{{ preview.item.base }}</h3><iframe :src="preview.url" :title="'PDF de '+preview.item.base" class="portal-pdf"></iframe></AppDialog><AppDialog v-if="confirming" title="Confirmar ciência" :busy="busy" @close="confirming=null"><p>Registrar ciência de {{ confirming.base }} com sua identidade? O registro inclui data e IP do acesso.</p><form class="vue-form" @submit.prevent="acknowledge"><label class="confirmation-check"><input v-model="confirmed" type="checkbox" required>Confirmo esta ação.</label><p v-if="formError" role="alert">{{ formError }}</p><footer><button class="secondary" type="button" :disabled="busy" @click="confirming=null">Cancelar</button><button class="secondary" type="submit" :disabled="busy||!confirmed">Confirmar ciência</button></footer></form></AppDialog></template>
